float hash(float num1, float num2) {
    return fract(72.53 * sin((num1 + 7.0) * 315.0 + 127.0) * cos((num2+11.0) * 513.0) * 7759.0);
}

float rand(float num) {
    return hash(num, 3.0);
}

vec2 randxy(float num) {
    return vec2(hash(num,1.0), hash(num,2.0));
}

float height(vec2 p, float t) {
    p/=30.0;
    const float n = 17.0;
    float v=0.0;
    for(float i=0.0;i<n;++i) {
        vec2 c = randxy(i)*2.0-1.0;
        float r = (1.0+rand(i))/4.0;
        vec2 xy = c+vec2(cos(t*(0.5+rand(i+100.0)/2.0)+rand(i)*6.0)*r, sin(t*(0.5+rand(i+200.0)/2.0)+rand(i)*6.0)*r);
        float l = length(p-xy);
        v += pow(l,0.3);
    }
    return v*2.0;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    uv*=30.0;
    float t = iTime*2.0;
    float h0 = height(uv,t);
    float h1 = height(uv+vec2(0.2,0.0),t);
    float h2 = height(uv+vec2(0.0,0.2),t);
    vec3 n = cross(normalize(vec3(0.2, 0.0, h1-h0)), normalize(vec3(0.0, 0.2, h2-h0)));
    vec3 l = normalize(vec3(30.0*cos(t),30.0*sin(t) ,15.0));
    float v = dot(n, l);
    float cf = v>0.0?acos(v)/acos(0.0)*0.5:acos(-v);
    vec3 col=vec3(clamp(cf,0.2,1.0),clamp(cf*1.5,0.3,1.0), clamp(cf*2.0,0.3,1.0));
    fragColor = vec4(col,1.0);
}
